-- 0058 v3 · POSTFLIGHT (solo lectura). Tras aplicar: todo «ok». Antes de aplicar, las filas H* salen «pendiente».
begin read only;
select 'H1 anon no lee profiles',                     case when not has_table_privilege('anon', 'public.profiles', 'SELECT') then 'ok' else 'pendiente' end;
select 'H1 authenticated sigue leyendo profiles',     case when has_any_column_privilege('authenticated', 'public.profiles', 'SELECT') then 'ok' else 'ROTO' end;
select 'H6 authenticated: columnas legibles',          case when (select string_agg(column_name, ',' order by column_name) from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'profiles' and has_column_privilege('authenticated', 'public.profiles', c.column_name, 'SELECT')) = 'avatar,id,level,points,region,username' then 'ok' else 'pendiente' end;
select 'H6 authenticated no lee credits/is_admin/last_seen_at', case when not has_column_privilege('authenticated', 'public.profiles', 'credits', 'SELECT') and not has_column_privilege('authenticated', 'public.profiles', 'is_admin', 'SELECT') and not has_column_privilege('authenticated', 'public.profiles', 'last_seen_at', 'SELECT') then 'ok' else 'pendiente' end;
select 'H7 vistas heredadas fuera de clientes',        (select count(*) from unnest(array['ranking_level','ranking_collection','ranking_market','ranking_rarities']) v where has_table_privilege('anon', ('public.' || v)::regclass, 'SELECT') or has_table_privilege('authenticated', ('public.' || v)::regclass, 'SELECT'))::text || ' (esperado 0)';
select 'H1 authenticated conserva UPDATE de columnas', case when (select string_agg(column_name, ',' order by column_name) from information_schema.column_privileges where table_schema = 'public' and table_name = 'profiles' and privilege_type = 'UPDATE' and grantee = 'authenticated') = 'avatar,region,username' then 'ok' else 'ROTO' end;
select 'H2 sin INSERT/DELETE de cliente en profiles',  case when not has_table_privilege('authenticated', 'public.profiles', 'INSERT') and not has_table_privilege('authenticated', 'public.profiles', 'DELETE') and not has_table_privilege('anon', 'public.profiles', 'INSERT') then 'ok' else 'pendiente' end;
select 'H2 política «crea tu perfil» retirada',        case when not exists (select 1 from pg_policy where polrelid = 'public.profiles'::regclass and polname = 'crea tu perfil') then 'ok' else 'pendiente' end;
select 'H3 tablas con TRUNCATE para clientes',         (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind in ('r','p') and (has_table_privilege('anon', c.oid, 'TRUNCATE') or has_table_privilege('authenticated', c.oid, 'TRUNCATE')))::text || ' (esperado 0)';
select 'H5 vistas escribibles por clientes',           (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'v' and (has_table_privilege('anon', c.oid, 'INSERT') or has_table_privilege('anon', c.oid, 'UPDATE') or has_table_privilege('anon', c.oid, 'DELETE') or has_table_privilege('authenticated', c.oid, 'INSERT') or has_table_privilege('authenticated', c.oid, 'UPDATE') or has_table_privilege('authenticated', c.oid, 'DELETE')))::text || ' (esperado 0)';
select 'H5 vistas públicas siguen legibles',           case when has_table_privilege('anon', 'public.ranking_points', 'SELECT') and has_table_privilege('anon', 'public.pickem_questions_public', 'SELECT') and has_table_privilege('authenticated', 'public.card_photos', 'SELECT') then 'ok' else 'ROTO' end;
select 'H4 helpers ejecutables por anon',              (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('recompute_standings','recompute_team_stats','recompute_player_event_stats','expire_offers','_release_listing_offers','_check_wash','_check_rate','_check_price_band','_price_anchor','_asset_refresh_best') and (has_function_privilege('anon', p.oid, 'EXECUTE') or has_function_privilege('authenticated', p.oid, 'EXECUTE')))::text || ' (esperado 0)';
select 'H4 service_role conserva recompute_*',        case when has_function_privilege('service_role', 'public.recompute_standings(text)', 'EXECUTE') and has_function_privilege('service_role', 'public.recompute_team_stats(text,text)', 'EXECUTE') and has_function_privilege('service_role', 'public.recompute_player_event_stats(text)', 'EXECUTE') then 'ok' else 'ROTO' end;
select 'funciones de mercado con auth.uid() intactas', case when has_function_privilege('authenticated', 'public.cancel_offer(uuid)', 'EXECUTE') then 'ok' else 'ROTO' end;
rollback;
